/* Design System — colors, typography, spacing, grid, motion, focus-visible */

/* Color palette */
:root{
  --color-bg-light:#f8f9fa;
  --color-bg-dark:#212b36;
  --color-fg-light:#212b36;
  --color-fg-dark:#f8f9fa;
  --color-accent:#3b82f6;
  --color-accent-hover:#2563eb;
  --color-contrast:#334155;
  --color-reduced-motion:#e5e7eb;
}

@media (prefers-color-scheme: dark){
  :root{
    --color-bg-light:#212b36;
    --color-bg-dark:#f8f9fa;
    --color-fg-light:#f8f9fa;
    --color-fg-dark:#212b36;
    --color-accent:#60a5fa;
    --color-accent-hover:#3b82f6;
    --color-contrast:#9ca3af;
    --color-reduced-motion:#3f4555;
  }
}

/* Typography */
html{font-size:1rem;line-height:1.5}
body{
  margin:0;
  font-family:system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif;
  color:var(--color-fg-light);
  background:var(--color-bg-light);
  max-width:64ch;
  padding:clamp(20px,5vw,40px)
}
h1{font-size:clamp(1.5rem,3vw,3rem);font-weight:700;line-height:1.05;margin:0 0 1rem}
h2{font-size:clamp(1.25rem,2vw,2rem);font-weight:700;line-height:1.15;margin:1.5rem 0 1rem}
h3{font-size:1.25rem;font-weight:600;line-height:1.3;margin:1rem 0 0.5rem}
p{margin:0 0 1rem}
a{color:var(--color-accent-text);text-decoration:none}
a:hover{color:var(--color-accent-hover)}

/* Focus-visible */
*:focus-visible{outline:2px solid var(--color-accent)}

/* Motion */
html{transition:all 200ms ease-in-out}
@media (prefers-reduced-motion: reduce){
  *{transition:none!important;animation:none!important}
}

/* Grid / spacing */
@media (min-width:640px){
  .grid{grid-template-columns:repeat(auto-fit,minmax(250px,1fr))}
}

/* Spacing scale using 0.25rem unit */
.s-0{margin:0;padding:0}
.s-1{margin:.25rem;padding:.25rem}
.s-2{margin:.5rem;padding:.5rem}
.s-3{margin:.75rem;padding:.75rem}
.s-4{margin:1rem;padding:1rem}
.s-5{margin:1.5rem;padding:1.5rem}
.s-6{margin:2rem;padding:2rem}
.s-7{margin:3rem;padding:3rem}

